<template><main style="max-width:900px;margin:100px auto;padding:16px"><h1>My Vault</h1><div style="display:flex;gap:8px"><input v-model="vault.query" placeholder="Search your vault" style="flex:1;padding:12px;border-radius:999px;background:#111;border:1px solid #333;color:#fff" /><button v-if="vault.query" @click="vault.query=''">X</button></div><div style="display:flex;gap:8px;margin:12px 0;flex-wrap:wrap"><button>All Items</button><button>Favorites</button><button>Recently Used</button><button>Login</button><button>Alias</button><button>Note</button><button>Card</button><button>Identity</button><button>Other</button></div><RouterLink to="/new-item" class="btn-primary" style="text-decoration:none">+ New Item</RouterLink><div v-if="vault.filtered.length===0" style="padding:40px;text-align:center;color:#a1a1aa">No matching items — try another search or create a new item.</div><div v-for="it in vault.filtered" :key="it.id" class="card" style="padding:16px;margin:10px 0"><b>{{it.title}}</b> — {{it.type}}<br><span style="color:#a1a1aa">{{it.website||it.email||''}}</span></div></main></template>
<script setup lang="ts">import {onMounted} from 'vue'; import {useVault} from '../stores/vault'; const vault=useVault(); onMounted(()=>vault.load());</script>
